/* 校园提醒 App 安装包 v1.0.5 - base64 内嵌，点击下载时生成 Blob，不依赖外部文件 */
/* 重新打包 APK 后，运行 tools/embed-apk.py 重新生成本文件即可同步更新 */
var APP_APK_BASE64 = "";
var APP_APK_SIZE_KB = 207.2;
var APP_VERSION = "1.0.5";
var APP_APK_SHA256 = "75ea916add649858819a2ca60503df0e0659762bfb322a6572c38ad6d07e7f98";

function triggerAppDownload(){
  try{
    var b64=(typeof APP_APK_BASE64!=="undefined")?APP_APK_BASE64:"";
    if(!b64){return false;}
    var bin=atob(b64);
    var len=bin.length;
    var bytes=new Uint8Array(len);
    for(var i=0;i<len;i++){bytes[i]=bin.charCodeAt(i);}
    var blob=new Blob([bytes],{type:"application/vnd.android.package-archive"});
    var url=URL.createObjectURL(blob);
    var a=document.createElement("a");
    a.href=url;
    a.download="campus-reminder-1.0.5.apk";
    document.body.appendChild(a);
    a.click();
    setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url);},1500);
    return true;
  }catch(e){console.error("app download error:",e);return false;}
}
